Le calcul passe en entiers (produit vérifié contre le débordement) avec arrondi au-dessus.
```swift
// Fixture FICTIVE du banc Nova (cas correctif_swift) — version corrigée de référence.
// Argent en micro-dollars entiers, jamais en flottants ; coût partiel arrondi au-dessus.

/// Coût en micro-dollars de `jetons` jetons facturés `prixMicroParMillion` µ$ par million de jetons.
public func coutMicroDollars(jetons: Int, prixMicroParMillion: Int64) -> Int64 {
    precondition(jetons >= 0 && prixMicroParMillion >= 0, "montant négatif")
    let (produit, debord) = Int64(jetons).multipliedReportingOverflow(by: prixMicroParMillion)
    precondition(!debord, "dépassement de capacité")
    return produit / 1_000_000 + (produit % 1_000_000 == 0 ? 0 : 1)
}

/// Coût total d'une liste d'appels (jetons, prix).
public func coutTotalMicroDollars(_ appels: [(jetons: Int, prixMicroParMillion: Int64)]) -> Int64 {
    var total: Int64 = 0
    for a in appels { total += coutMicroDollars(jetons: a.jetons, prixMicroParMillion: a.prixMicroParMillion) }
    return total
}
```

